//! The D3D11 leaves game adapters link through ReScaleFrame::Graphics: state snapshots and
//! binding restores, texture descriptions and dumps, constant-buffer reads, resource roles and the
//! frame tap. Before the Rust port these were C++ compiled into each consumer; the Runtime uses
//! the same modules through its rlib dependency, so adapters do not link the Runtime archive.

/// C bindings this crate sees: its two private headers (generated by build.rs) with the public SDK
/// headers from rsf-game-sys. The Runtime's sys re-exports this module.
#[allow(
    non_camel_case_types,
    non_upper_case_globals,
    non_snake_case,
    dead_code,
    clippy::all
)]
pub mod sys {
    pub use rsf_game_sys::*;
    include!(concat!(env!("OUT_DIR"), "/sys.rs"));
}

pub mod capture_names;
pub mod capture_pixels;
#[cfg(windows)]
pub mod com_ref;
#[cfg(windows)]
pub mod constant_buffer_read;
#[cfg(windows)]
pub mod d3d11_output;
#[cfg(windows)]
pub mod d3d11_output_platform;
#[cfg(windows)]
pub mod d3d11_state;
pub mod dump_options;
#[cfg(windows)]
pub mod dxgi_format;
#[cfg(windows)]
pub mod frame_tap;
#[cfg(windows)]
pub mod resource_roles;
#[cfg(windows)]
pub mod texture_dump;
